"""La revisión de gcode: es lo que impide mandar a la K2 un gcode que la golpee."""
import base64

import gcode

CABECERA = """; HEADER_BLOCK_START
; generated by Creality_Print V7.2.2.5483 on 2026-09-27 at 00:24:27
; total layer number: 2
; HEADER_BLOCK_END

; multicolor_method = 0 
; external perimeters extrusion width = 0.42mm

; EXECUTABLE_BLOCK_START
;TYPE:Custom
START_PRINT EXTRUDER_TEMP=220 BED_TEMP=50
T0
G1 X105 Y-1 F30000
G1 X155 E9
"""

PIE = """;TYPE:Custom
END_PRINT
; EXECUTABLE_BLOCK_END
; CONFIG_BLOCK_START
; printer_model = {modelo}
; printable_area = 0x0,{cama}x0,{cama}x{cama},0x{cama}
; printable_height = {cama}
; filament_type = PLA;PLA
; filament_colour = #FFFFFF;#000000
; filament_settings_id = "Hyper PLA @Creality K2 0.4 nozzle";"CR-PLA @Creality K2 0.4 nozzle"
; estimated printing time (normal mode) = 11m 57s
; CONFIG_BLOCK_END
"""


def escribir(tmp_path, capas, modelo="Creality K2", cama=260, nombre="p.gcode"):
    ruta = tmp_path / nombre
    ruta.write_text(CABECERA + capas + PIE.format(modelo=modelo, cama=cama), encoding="utf-8")
    return ruta


def capas_en(x0, x1, y0=100, y1=150):
    return f""";LAYER_CHANGE
;TYPE:Outer wall
G1 X{x0} Y{y0} F30000
G1 X{x1} Y{y1} E3
G1 Z0.4
"""


def test_gcode_bueno_es_apto(tmp_path):
    inf = gcode.analizar(escribir(tmp_path, capas_en(100, 150)), "Creality K2", (260, 260, 260))
    assert inf.apto, inf.problemas
    assert inf.generado_por.startswith("Creality_Print V7.2.2")
    assert inf.tiempo_estimado == "11m 57s"
    assert inf.herramientas == [0]


def test_la_purga_del_arranque_no_cuenta_como_pieza(tmp_path):
    # La línea de purga va a Y=-1 antes de la primera capa; es de la máquina.
    inf = gcode.analizar(escribir(tmp_path, capas_en(100, 150)), "Creality K2", (260, 260, 260))
    assert inf.desplazamientos.y_min == -1
    assert inf.pieza.y_min == 100


def test_cambio_de_filamento_a_la_rampa_no_cuenta(tmp_path):
    capas = capas_en(100, 150) + ";TYPE:Custom\nG0 Y291.5 F12000\nT1\n;TYPE:Inner wall\nG1 X120 Y120 E1\n"
    inf = gcode.analizar(escribir(tmp_path, capas), "Creality K2", (260, 260, 260))
    assert inf.apto, inf.problemas
    assert inf.herramientas == [0, 1]


def test_perfil_k2_pro_se_rechaza_aunque_su_cama_diga_300(tmp_path):
    # El fallo real: Creality Print laminó con K2 Pro y el gcode se creía dentro de su cama.
    ruta = escribir(tmp_path, capas_en(28, 277.7, 25, 274.9), modelo="Creality K2 Pro", cama=300)
    sin_cama_real = gcode.analizar(ruta, "Creality K2")
    assert len(sin_cama_real.problemas) == 1  # solo el modelo: contra su propia cama "cabe"
    inf = gcode.analizar(ruta, "Creality K2", (260, 260, 260))
    assert not inf.apto
    assert any("K2 Pro" in p for p in inf.problemas)
    assert any("sale de la cama" in p for p in inf.problemas)


def test_modelo_equivocado_es_problema(tmp_path):
    inf = gcode.analizar(escribir(tmp_path, capas_en(100, 150), modelo="Creality K1C", cama=220),
                         "Creality K2", (260, 260, 260))
    assert not inf.apto


def test_movimientos_relativos_se_suman(tmp_path):
    capas = capas_en(250, 255) + "G91\nG1 X10\nG90\n"
    inf = gcode.analizar(escribir(tmp_path, capas), "Creality K2", (260, 260, 260))
    assert inf.pieza.x_max == 265
    assert not inf.apto


def test_sin_miniaturas_avisa(tmp_path):
    inf = gcode.analizar(escribir(tmp_path, capas_en(100, 150)), "Creality K2", (260, 260, 260))
    assert any("miniaturas" in a for a in inf.avisos)


def test_orca_sin_malla_avisa(tmp_path):
    ruta = escribir(tmp_path, capas_en(100, 150))
    ruta.write_text(ruta.read_text().replace("Creality_Print V7.2.2.5483", "OrcaSlicer 2.4.2"))
    inf = gcode.analizar(ruta, "Creality K2", (260, 260, 260))
    assert any("BED_MESH_PROFILE" in a for a in inf.avisos)


def test_insertar_miniaturas_formato_creality(tmp_path):
    ruta = escribir(tmp_path, capas_en(100, 150))
    png = b"\x89PNG\r\n\x1a\n" + b"x" * 200
    gcode.insertar_miniaturas(ruta, [(96, 96, png), (300, 300, png)])
    texto = ruta.read_text()
    assert texto.index("; thumbnail begin 96x96") > texto.index("; multicolor_method")
    assert texto.index("; thumbnail begin 96x96") < texto.index("; external perimeters")
    b64 = base64.b64encode(png).decode()
    assert f"; thumbnail begin 96x96 {len(b64)}" in texto
    for linea in texto.splitlines():
        if linea.startswith("; ") and set(linea[2:]) <= set(b64 + "="):
            assert len(linea) <= 80
    inf = gcode.analizar(ruta, "Creality K2", (260, 260, 260))
    assert inf.miniaturas == ["96x96", "300x300"]
    assert inf.apto
    # Idempotente: no mete otra tanda.
    gcode.insertar_miniaturas(ruta, [(96, 96, png)])
    assert ruta.read_text().count("thumbnail begin") == 2


def test_resumen_filamentos(tmp_path):
    capas = capas_en(100, 150) + "T1\nG1 X110 Y110 E1\n"
    r = gcode.analizar(escribir(tmp_path, capas), "Creality K2", (260, 260, 260)).resumen()
    assert [f["extrusor"] for f in r["filamentos"]] == [1, 2]
    assert r["filamentos"][1]["color"] == "#000000"
    assert r["filamentos"][1]["perfil"] == "CR-PLA @Creality K2 0.4 nozzle"


def test_partir_lista():
    assert gcode.partir_lista('"A b";"C"') == ["A b", "C"]
    assert gcode.partir_lista("#FFF;#000") == ["#FFF", "#000"]
    assert gcode.partir_lista("") == []
